// src/core/pipeline.ts
import { readFile as readFile2 } from "fs/promises";
import { dirname as dirname3, resolve as resolvePath } from "path";
import { getAST } from "@gram-lang/parser";
import { compile } from "@gram-lang/kitchen";
import { analyze } from "@gram-lang/analyzer";
import {
  loadModuleGraph,
  composeRecipe,
  finalizeComposed
} from "@gram-lang/modules";

// src/errors.ts
import { log } from "@clack/prompts";
var ExitCode = {
  Ok: 0,
  Error: 1,
  InternalError: 2
};
var GramCLIError = class extends Error {
  constructor(message, exitCode = ExitCode.InternalError) {
    super(message);
    this.exitCode = exitCode;
    this.name = "GramCLIError";
  }
  exitCode;
};

// src/core/module-host.ts
import { readFile } from "fs/promises";
import { dirname, resolve, relative, isAbsolute } from "path";
var AT_SPECIFIER_RE = /^@([^/]*)\/(.+)$/;
function confine(resolved, projectRoot, specifier) {
  const rel = relative(projectRoot, resolved);
  if (rel === "") return resolved;
  if (rel.startsWith("..") || isAbsolute(rel)) {
    throw new Error(
      `"${specifier}" resolves outside the project root (${projectRoot}).`
    );
  }
  return resolved;
}
function createCliModuleHost(projectRoot, paths, read = (uri) => readFile(uri, "utf-8")) {
  return {
    resolve(specifier, fromUri) {
      const atMatch = AT_SPECIFIER_RE.exec(specifier);
      if (atMatch) {
        const [, alias, rest] = atMatch;
        if (alias === "") {
          return confine(resolve(projectRoot, rest), projectRoot, specifier);
        }
        const aliasDir = paths?.[alias];
        if (aliasDir === void 0) {
          throw new Error(
            `"@${alias}/" is not declared. Add it to "paths:" in .gram/config.yaml (e.g. paths: { ${alias}: ./some/dir }).`
          );
        }
        return confine(
          resolve(projectRoot, aliasDir, rest),
          projectRoot,
          specifier
        );
      }
      const resolved = resolve(dirname(fromUri), specifier);
      return confine(resolved, projectRoot, specifier);
    },
    read
  };
}

// src/core/workspace.ts
import { access } from "fs/promises";
import { dirname as dirname2, resolve as resolve2 } from "path";
async function searchProjectRoot(start) {
  let dir = start;
  while (true) {
    try {
      await access(resolve2(dir, ".gram"));
      return dir;
    } catch {
    }
    const parent = dirname2(dir);
    if (parent === dir) return null;
    dir = parent;
  }
}
async function findProjectRoot(start = process.cwd()) {
  return await searchProjectRoot(start) ?? start;
}

// src/core/pipeline.ts
async function runPipeline(filePath, opts = {}) {
  const entryUri = resolvePath(filePath);
  let content;
  try {
    content = await readFile2(entryUri, "utf-8");
  } catch (err) {
    if (err.code === "ENOENT") {
      throw new GramCLIError(`File not found: ${filePath}`, ExitCode.Error);
    }
    throw err;
  }
  const projectRoot = await findProjectRoot(dirname3(entryUri));
  const host = createCliModuleHost(projectRoot, opts.paths);
  const graph = await loadModuleGraph(entryUri, host);
  const composed = composeRecipe(graph, {
    db: opts.db ?? {},
    lang: opts.lang,
    cache: opts.moduleCache,
    stock: opts.stock
  });
  const compiled = compile(
    composed.ast,
    opts.scaleFactor ? { scaleFactor: opts.scaleFactor } : void 0
  );
  const tagged = finalizeComposed(compiled, composed);
  const analyzed = !opts.skipAnalyzer && opts.db ? analyze(
    tagged,
    // Real DB entries always win on id collision (§D.6's
    // host-always-wins policy) — a stocked import whose binding
    // name happens to slugify to an existing ingredient id
    // (MODULE_BINDING_SHADOWS_INGREDIENT) must not silently
    // override that ingredient's real nutrition/mass data for
    // every other reference to it in the document.
    { ...composed.syntheticIngredients, ...opts.db },
    {
      bakersReference: opts.bakersReference,
      lang: opts.lang
    }
  ) : null;
  return { content, compiled: tagged, analyzed, usedStock: composed.usedStock };
}
export {
  ExitCode,
  GramCLIError,
  runPipeline
};
